const response = $input.first().json;
if (response.statusCode < 200 || response.statusCode >= 300) return [{ json: { statusCode: response.statusCode, body: response.body } }];
const result = response.body;
if (!Array.isArray(result.new_anomalies)) throw new Error('Resposta da API sem new_anomalies');
const alerts = result.new_anomalies.map(item => ({ series_id: item.series_id, timestamp: item.timestamp, anomaly_score: item.score, threshold: result.threshold, model_version: item.model_version, message: 'Ponto sinalizado pelo modelo; revisar antes de agir.' }));
return [{ json: { statusCode: response.statusCode, body: { inserted: result.inserted, duplicates: result.duplicates, alert_count: alerts.length, alerts } } }];

const result = $input.first().json;
if (result.statusCode !== 200 || !(result.body.alert_count > 0)) return [];
return [{ json: result.body }];
